PREFIX brick: <http://brickschema.org/schema/brick#>
PREFIX ref: <https://brickschema.org/schema/brick/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?point ?tsid WHERE {
  ?point brick:hasSubclass* brick:ElectricPower ;
         ref:hasTimeseriesId ?tsid .
}

PREFIX brick: <http://brickschema.org/schema/brick#>
PREFIX ref: <https://brickschema.org/schema/brick/ontology#>
SELECT ?point ?class ?tsid WHERE {
  ?point ?class .
  OPTIONAL{ ?point ref:hasTimeseriesId ?tsid }
}

PREFIX brick: <http://brickschema.org/schema/brick#>
PREFIX ref: <https://brickschema.org/schema/brick/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?point ?classLabel ?tsid WHERE {
  ?point ?class .
  FILTER( a ?class )
  ?point rdfs:label ?classLabel .
  OPTIONAL{ ?point ref:hasTimeseriesId ?tsid }
}

PREFIX brick: <http://brickschema.org/schema/brick#>
PREFIX ref: <https://brickschema.org/schema/brick/ontology#>
SELECT DISTINCT ?class WHERE {
  ?point a ?class .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?point ?tsid WHERE {
  ?point a brick:Building_Electrical_Meter .
  ?point ref:hasTimeseriesId ?tsid .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?point ?class ?tsid WHERE {
  ?point a ?class .
  FILTER( str(?class) LIKE "%Meter%" || str(?class) LIKE "%Power%" || str(?class) LIKE "%Electric%" )
  OPTIONAL{ ?point ref:hasTimeseriesId ?tsid }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?point ?class ?tsid WHERE {
  ?point a ?class .
  OPTIONAL{ ?point ref:hasTimeseriesId ?tsid }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?point ?tsid WHERE {
  ?point a brick:Electric_Power_Sensor .
  ?point ref:hasTimeseriesId ?tsid .
}
